E("G5_TB_65_559.1", "в ключе десятичная дробь $25{,}8$ была разорвана на «$25$, $8$»; $2{,}58:1{,}2=25{,}8:12$", k=r"должно быть $25{,}8 : 12$")
E("G5_TB_13_258а.2", "в условии второй ряд «$5\\,(?)\\,12$» слился с первым в «$6(66)115$»; закономерность $6\\cdot11=66$, $5\\cdot12=60$ подтверждает ключ $60$",
  q="В двух рядах число, заключённое в скобки, получается из чисел, стоящих по обе стороны скобок, в результате некоторых арифметических действий. Замените знак $«?»$ пропущенным числом: $6\\,(66)\\,11$ и $5\\,(?)\\,12$")
E("G5_TB_15_629", "значение выражения $963\\cdot273=262\\,899$ (в ключе и вариантах были арифметические ошибки в последних цифрах); пояснения очищены от служебных знаков",
  k=r"$(215 + 748) \cdot (591 - 318) = 262899$",
  dnew={0: (r"$(215 + 748) \cdot 591 - 318 = 568815$", r"Ученик не поставил скобки во втором действии, и из произведения $963\cdot591$ вычлось только $318$."),
        1: (r"$215 + 748 \cdot (591 - 318) = 204419$", r"Ученик не поставил скобки для первого действия, и по приоритету сначала выполнилось умножение $748\cdot273$."),
        2: (r"$(215 + 748) \cdot (318 - 591) = -262899$", r"Ученик выполнил вычитание во втором действии наоборот: из $318$ вычел $591$, получив отрицательный результат.")})
A = "неверный вариант совпадал с ключом по величине аргумента (значения аргумента определены с точностью до $2\\pi$, в банке главное значение из $(-\\pi;\\pi]$); заменён на реальную ошибку"
E("G11_TB_17_2*_17_9_a", A, dnew={2: (r"$1$", r"Ученик принял модуль числа $|z|=1$ за его аргумент.")})
E("G11_TB_17_2*_17_9_b", A, dnew={1: (r"$\dfrac{3\pi}{2}$", r"Ученик решил, что число $-1$ лежит на отрицательной мнимой оси.")})
E("G11_TB_17_2*_17_9_d", A, dnew={1: (r"$\pi$", r"Ученик решил, что число $-i$ лежит на отрицательной действительной оси.")})
E("G11_TB_17_2*_17_9_e", "вариант «$45$» — это $\\frac{\\pi}{4}$ в градусах, то есть тот же угол, что в ключе; заменён", dnew={0: (r"$\dfrac{3\pi}{4}$", r"Ученик взял точку $-1+i$ вместо $1+i$, перепутав знак действительной части.")})
