E("G11_TB_17_2*_17_10_d", A, dnew={2: (r"$-\dfrac{2\pi}{3}$", r"Ученик взял опорный угол $\frac{\pi}{3}$ (перепутал катеты) вместо $\frac{\pi}{6}$: $-\pi+\frac{\pi}{3}=-\frac{2\pi}{3}$.")})
E("G11_TB_17_2*_17_10_e", "вариант «$60$» — это $\\frac{\\pi}{3}$ в градусах, то есть тот же угол, что в ключе; заменён", dnew={0: (r"$\dfrac{\pi}{4}$", r"Ученик принял $\operatorname{tg}\varphi=1$ вместо $\sqrt{3}$.")})
